{
  "a_requests": [
    {
      "a_request": "R1",
      "b_asked": "서울특별시 동물보호 조례상 주인을 못 찾으면 무조건 안락사되는지 여부",
      "c_basis": "APPLIED",
      "d_claims": [
        {
          "a_text": "주인을 못 찾으면 무조건 안락사되는 것은 아니다. 서울특별시 동물보호 조례 제16조제3항에 따르면 구청장은 공고 시작일부터 10일이 지나도 소유자·관리자가 나타나지 않거나 소유자를 알 수 없는 경우 해당 동물을 법 제45조 또는 제46조에 따라 처리할 수 있다. 즉 처리 방법은 법에 따라 정해지며, 조례 자체에서는 안락사를 강제하지 않는다.",
          "b_ids": "동물보호:제16조제3항"
        }
      ],
      "e_status": "ANSWERED"
    }
  ]
}
